import type { QuizQuestion } from "@/types/quizzes";

// Extra "Check your understanding" questions. Every experiment already
// carries 3 questions in its content file; these add more so each check is
// 20 questions long, the same as titration. One at a time. Keyed by the experiment's `component`.

const ids = ["a", "b", "c", "d"];

function q(
  id: string,
  question: string,
  options: [string, string, string, string],
  correct: 0 | 1 | 2 | 3,
  explanation: string,
): QuizQuestion {
  // Rotate the options by a fixed amount per question so the right answer
  // is not always in the same slot. Same result on every build.
  let hash = 0;
  for (const ch of id) hash = (hash * 31 + ch.charCodeAt(0)) % 997;
  const shift = hash % 4;
  const rotated = [...options.slice(shift), ...options.slice(0, shift)];
  return {
    id,
    question,
    type: "multiple-choice",
    options: rotated.map((text, i) => ({ id: ids[i], text })),
    correctAnswer: ids[rotated.indexOf(options[correct])],
    explanation,
    points: 10,
  } as QuizQuestion;
}

